class QuorumStore:
    def __init__(self, peers, me):
        self.peers = peers  # list of follower clients
        self.me = me        # local durable log
        self.commit_index = 0

    def write(self, entry) -> bool:
        # 1. Durably store locally first. Crash before this = never acked.
        seq = self.me.append(entry)
        acks = 1  # leader counts itself
        # 2. Replicate in parallel; wait for majority, not all.
        for p in self.peers:
            try:
                if p.replicate(entry, seq, timeout_ms=200):
                    acks += 1
            except TimeoutError:
                continue  # slow follower does not block commit if majority reached
        needed = (len(self.peers) + 1) // 2 + 1
        # 3. Commit only on quorum. This is the durability line.
        if acks >= needed:
            self.commit_index = seq
            self.me.mark_committed(seq)
            return True
        return False  # caller must retry; never expose as committed
